const r = await tools.mcp__status__status_set({
  goal: "Create hello.txt containing exactly \"hello\" and commit it as requested.",
  tldr: "Work has started; I’m checking the repository before making the commit.",
  now: "Inspecting the working tree and repository state.",
  done: ["Request received; no files changed yet."],
  next: ["Check git status.", "Create hello.txt and commit it.", "Verify the commit."],
  state: "working"
});
text(r);

const patch = "*** Begin Patch
*** Add File: <root>/project/hello.txt
+hello
*** End Patch";
text(await tools.apply_patch(patch));

